insert into cac.articles (slug,title,category,excerpt,image_path,image_alt,read_minutes,featured,published_at) values ('mk1-gti-new-life','How a Mk1 GTI found a new life','Restoration','The simple, honest restoration keeping a ’70s icon on Norfolk roads.','homepage/news-gti.webp','Owner working on the engine of an orange 1970s hatchback',6,true,'2026-11-20'),('le-mans-2027-dates','Le Mans 2027: dates set for the 95th running','WEC','Race week runs 9–13 June, with the 24 Hours itself on 12–13 June.','homepage/lemans.webp','Endurance prototype at night with fairground wheel behind',3,false,'2026-11-18'),('british-classics-on-the-road','The enthusiasts keeping British classics on the road','People','Meet the owners who drive their cars all year round.','homepage/news-2.webp','Smiling driver in an open-face helmet',4,false,'2026-11-15'),('carburettors-vs-injection','Carburettors vs. injection: what’s right for your classic?','Technical','The honest pros and cons of converting.','homepage/news-3.webp','Close-up of a classic engine with twin carburettors',6,false,'2026-11-12'),('winter-lay-up-checks','Five checks before you lay up your classic for winter','Technical','Battery, tyres, fluids, covers and paperwork.','homepage/gal-wheel.webp','Wood-rimmed steering wheel and dials',5,false,'2026-11-09');
insert into cac.community_highlights (handle,title,excerpt,image_path,image_alt,sort) values ('@norfolkseries','Bringing a Series IIA back to life','A slow, satisfying restoration, one weekend at a time.','homepage/com-1.webp','Owner working on the front of an old green off-roader',0),('@elliesgarage','My first engine rebuild','A steep learning curve, a few setbacks and a running engine at last.','homepage/com-2.webp','Woman working on an engine under a raised bonnet',1),('@aircooleduk','A Norfolk dawn run with friends','Crisp roads, good company and a reminder of why we do this.','homepage/com-3.webp','Classic sports cars driving a country lane at sunrise',2);
