insert into cac.partner_features (partner_id,block_key,title,body,extra,image_path,image_alt,cta_label,cta_url,cta2_label,cta2_url,countdown_to) select id,'detail_of_month','Detail of the Month','A 1970s BMW 3 Series brought back to its best by Auto Opulence in Norwich: deep interior clean, paint correction, engine bay detail and a Gyeon ceramic coating on the original paint.','Cars and Coffee member offers coming soon.','homepage/ao-e21.webp','Red classic BMW 3 Series gleaming after a ceramic coating in the Auto Opulence studio','Read the case study','https://autoopulence.co.uk/case-studies/bmw-e21-3-series-restoration-detail','Explore detailing services','https://autoopulence.co.uk/services',null from cac.partners where slug='auto-opulence';
insert into cac.partner_features (partner_id,block_key,title,body,extra,image_path,image_alt,cta_label,cta_url,cta2_label,cta2_url,countdown_to) select id,'livery_of_week','Livery of the Week','This week’s standout is a blue and orange track-car livery for grassroots racing. Race Car Graphics design and fit liveries, number kits and sponsor graphics for club racers and race teams.','December challenge: retro endurance. Winner featured on the homepage.','homepage/rcg.webp','Blue and orange touring car with race number 66','Enter the challenge','/community/livery-challenge','Get a livery quote','https://racecargraphics.uk/race-car-graphics-home','2026-12-13T23:59:00Z' from cac.partners where slug='race-car-graphics';
insert into cac.partner_features (partner_id,block_key,title,body,extra,image_path,image_alt,cta_label,cta_url,cta2_label,cta2_url,countdown_to) select id,'race_night','Race Night at Le Man Cave','Full-motion racing simulators, a 160ft digital Scalextric and a motorbike simulator in Norwich. Join our members’ race night, or book Le Man Cave for your own car club meet.','Members’ race night: Thursday 10 December, 7pm.','homepage/lmc-sim.webp','Driver laughing in a racing simulator rig at Le Man Cave','Book race night','/events/members-race-night-dec-2026','Car club meets at Le Man Cave','https://lemancave.co.uk/car-club-meet-venue-norfolk','2026-12-10T19:00:00Z' from cac.partners where slug='le-man-cave';
insert into cac.sponsored_slots (advertiser,title,body,image_path,image_alt,cta_label,cta_url,starts_at,ends_at) values ('Sample advertiser','Performance parts for road and track','Quality components, trusted by enthusiasts.','homepage/sponsored.webp','Drilled brake disc and red calliper','Shop now','https://example.com',now(),now()+interval '30 days');
insert into cac.faqs (question,answer,sort) values ('How do I join Cars and Coffee UK?','Tap Join, sign in with Google, Apple or your email, and fill in a short application. Our team reviews every application, usually within 24 hours. If a member recommended you, you go into the fast-track queue.',0),('How do I recommend a friend?','Once you’re a member, open your profile and tap Recommend a mate. Share your invite link or QR code by WhatsApp, email or text. When your friend is approved you’re automatically connected as friends.',1),('Are meets free?','Most breakfast meets are free; we just ask you to RSVP so we can plan parking. Tours, garage nights and watch parties are ticketed, and the price is shown on each event.',2),('Do I have to own a particular type of car?','No. Classics, modern performance cars, track cars, daily drivers, or no car at all: everyone who loves cars is welcome.',3),('Are events open to non-members?','Most events are open to everyone. Members-only events are clearly marked on the event page.',4),('How do I list my business in the directory?','Choose List your business in the directory, add your details and services, and we’ll check and publish your listing. Featured placements on the homepage are available as a paid upgrade.',5),('How do I advertise with Cars and Coffee UK?','Visit Advertise with us to see formats and rates, then start a campaign in the advertiser portal. Every ad is reviewed before it goes live.',6);
